<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { ConceptoCuentaFlujo, CuentaContableFlujo, CuentaFlujoCaja } from '../interfaces/cuenta-flujo-caja.interface'
import { asociarCuentaFlujoCaja, buscarCuentasContablesFlujo, cambiarEstadoCuentaFlujoCaja, eliminarCuentaFlujoCaja, listarConceptosCuentaFlujo, listarCuentasFlujoCaja } from '../services/cuenta-flujo-caja'

const concepts = ref<ConceptoCuentaFlujo[]>([]), rows = ref<CuentaFlujoCaja[]>([]), selectedConcept = ref<number | null>(null), accountQuery = ref(''), accounts = ref<CuentaContableFlujo[]>([]), selectedAccount = ref<CuentaContableFlujo | null>(null), loading = ref(false), error = ref(''), success = ref('')
const concept = computed(() => concepts.value.find(x => x.id === selectedConcept.value))
let timer: ReturnType<typeof setTimeout> | undefined
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function loadConcepts() { loading.value = true; try { concepts.value = await listarConceptosCuentaFlujo(); if (!selectedConcept.value && concepts.value.length) { selectedConcept.value = concepts.value[0]!.id; await loadAccounts() } } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function loadAccounts() { if (!selectedConcept.value) { rows.value = []; return } loading.value = true; error.value = ''; try { rows.value = await listarCuentasFlujoCaja(selectedConcept.value) } catch (e) { error.value = message(e) } finally { loading.value = false } }
function searchAccounts() { selectedAccount.value = null; clearTimeout(timer); if (accountQuery.value.trim().length < 2) { accounts.value = []; return } timer = setTimeout(async () => { try { accounts.value = await buscarCuentasContablesFlujo(accountQuery.value.trim()) } catch (e) { error.value = message(e) } }, 300) }
function selectAccount(item: CuentaContableFlujo) { selectedAccount.value = item; accountQuery.value = `${item.cta_contable} · ${item.descripcion}`; accounts.value = [] }
async function associate() { if (!selectedConcept.value || !selectedAccount.value) return; loading.value = true; error.value = ''; try { await asociarCuentaFlujoCaja({ concepto_flujo_caja_id: selectedConcept.value, cuenta_contable_id: selectedAccount.value.id }); success.value = 'Cuenta contable asociada correctamente.'; accountQuery.value = ''; selectedAccount.value = null; await loadAccounts() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: CuentaFlujoCaja) { const action = item.activo ? 'inactivar' : 'activar'; if (!confirm(`¿Desea ${action} la cuenta ${item.cuenta_contable.cta_contable}?`)) return; loading.value = true; try { await cambiarEstadoCuentaFlujoCaja(item.id); success.value = `Cuenta ${item.activo ? 'inactivada' : 'activada'} correctamente.`; await loadAccounts() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function remove(item: CuentaFlujoCaja) { if (!confirm(`¿Retirar la cuenta ${item.cuenta_contable.cta_contable} de este concepto?`)) return; loading.value = true; try { await eliminarCuentaFlujoCaja(item.id); success.value = 'Cuenta retirada del concepto correctamente.'; await loadAccounts() } catch (e) { error.value = message(e) } finally { loading.value = false } }
onMounted(loadConcepts)
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Cuentas de flujo de caja</nav><header class="hero"><div class="mark">FC</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Cuentas de flujo de caja</h1><p>Asociación de cuentas contables con conceptos del estado de flujo de efectivo.</p></div><strong>{{rows.length}} cuentas asociadas</strong></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="workspace"><aside><h2>Conceptos</h2><p>Seleccione una clasificación</p><button v-for="item in concepts" :key="item.id" :class="{selected:selectedConcept===item.id}" @click="selectedConcept=item.id;loadAccounts()"><b>{{item.codigo}}</b><span>{{item.nombre}}</span><small>{{item.actividad}} · {{item.naturaleza}}</small></button><div v-if="!concepts.length&&!loading" class="asideempty">No existen conceptos activos.</div></aside><main><header><div><small>CONCEPTO SELECCIONADO</small><h2>{{concept?.codigo}} · {{concept?.nombre||'Seleccione un concepto'}}</h2></div><span v-if="concept" :class="concept.naturaleza==='INGRESO'?'income':'expense'">{{concept.naturaleza}}</span></header><form v-if="concept" class="associate" @submit.prevent="associate"><label>Cuenta contable<div class="lookup"><input v-model.trim="accountQuery" placeholder="Buscar por código o descripción" @input="searchAccounts"><ul v-if="accounts.length"><li v-for="item in accounts" :key="item.id" @click="selectAccount(item)"><b>{{item.cta_contable}}</b> · {{item.descripcion}}</li></ul></div></label><button :disabled="!selectedAccount||loading">+ Asociar cuenta</button></form><div v-if="loading" class="empty">Procesando…</div><div v-else-if="concept&&!rows.length" class="empty">Este concepto aún no tiene cuentas asociadas.</div><div v-else-if="rows.length" class="scroll"><table><thead><tr><th>#</th><th>Cuenta contable</th><th>Descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="(item,index) in rows" :key="item.id"><td>{{index+1}}</td><td><b>{{item.cuenta_contable.cta_contable}}</b></td><td>{{item.cuenta_contable.descripcion}}</td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVA':'INACTIVA'}}</span></td><td class="actions"><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button><button class="delete" @click="remove(item)">Retirar</button></td></tr></tbody></table></div></main></section></div></template>

